package com.ruoyi.metal.service;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
class ProcessConsumptionServiceTest {
 private Map<String,Object> batch(String state,String raw,String semi,String returned,String output){var r=new LinkedHashMap<String,Object>();r.put("status",state);r.put("rawIssuedWeight",raw);r.put("semiIssuedWeight",semi);r.put("rawReturnedWeight",returned);r.put("outputWeight",output);r.put("outputQuantity",10L);r.put("documentCount",3L);return r;}
 private Map<String,Object> settled(){var r=batch("SETTLED","300","0","100","190");r.put("reportId",4L);r.put("reportIssuedWeight","300");r.put("reportReturnedWeight","290");r.put("reportLossWeight","10");r.put("reportAverageLoss","1");r.put("reportCompletedQuantity",10L);r.put("reportVoided",false);r.put("reportStatus","ABNORMAL");return r;}
 @Test void openIsProvisional(){var r=ProcessConsumptionService.calculateBatch(batch("OPEN","300","0","100","190"));assertEquals("200.000000",r.get("netInputWeight"));assertEquals("10.000000",r.get("provisionalDifferenceWeight"));assertNull(r.get("settledLossWeight"));assertNull(r.get("averageLoss"));assertNull(r.get("settledCompletedQuantity"));}
 @Test void settledUsesSnapshotAndFlagsMismatch(){var r=settled();ProcessConsumptionService.calculateBatch(r);assertEquals("10.000000",r.get("settledLossWeight"));assertEquals("SETTLED",r.get("state"));r.put("reportLossWeight","11");ProcessConsumptionService.calculateBatch(r);assertEquals("REVIEW",r.get("state"));assertEquals("11.000000",r.get("settledLossWeight"));}
 @Test void mixedKeepsFinalAndProvisionalSeparate(){var r=ProcessConsumptionService.summarize(List.of(ProcessConsumptionService.calculateBatch(settled()),ProcessConsumptionService.calculateBatch(batch("OPEN","20","190","0","200"))));assertEquals("PARTIAL",r.get("state"));assertEquals("410.000000",r.get("netInputWeight"));assertEquals("10.000000",r.get("settledLossWeight"));assertEquals("10.000000",r.get("provisionalDifferenceWeight"));assertEquals("1.000000",r.get("averageLoss"));assertEquals(10L,r.get("settledCompletedQuantity"));}
 @Test void voidAndMissingAreNotCurrentZeroReports(){var gone=ProcessConsumptionService.calculateBatch(batch("VOID","1000","0","0","0"));var summary=ProcessConsumptionService.summarize(List.of(gone));assertEquals("NO_ACTIVE",summary.get("state"));assertEquals("0.000000",summary.get("issuedWeight"));assertEquals("NOT_STARTED",ProcessConsumptionService.summarize(List.of()).get("state"));var missing=ProcessConsumptionService.calculateBatch(batch("SETTLED","100","0","0","90"));assertEquals("REVIEW",missing.get("state"));assertNull(missing.get("settledLossWeight"));assertNull(ProcessConsumptionService.summarize(List.of(missing)).get("settledLossWeight"));}
 @Test void exactDecimalsNoZeroDivision(){var r=ProcessConsumptionService.calculateBatch(batch("OPEN","0.123456","0.000001","0.000002","0.100000"));assertEquals("0.023455",r.get("provisionalDifferenceWeight"));assertNull(ProcessConsumptionService.summarize(List.of(r)).get("averageLoss"));}
 @Test void decimalQuantityFromJdbcIsAnInteger(){var r=settled();r.put("outputQuantity","10.000000");assertEquals("SETTLED",ProcessConsumptionService.calculateBatch(r).get("state"));}
 @Test void invalidAverageIsPreservedButFlagged(){var r=settled();r.put("reportAverageLoss","999");assertEquals("REVIEW",ProcessConsumptionService.calculateBatch(r).get("state"));assertEquals("999.000000",r.get("averageLoss"));r.put("reportAverageLoss",null);assertEquals("REVIEW",ProcessConsumptionService.calculateBatch(r).get("state"));}
 @Test void missingCompletedNeverBecomesZero(){var r=settled();r.put("reportCompletedQuantity",null);var s=ProcessConsumptionService.summarize(List.of(ProcessConsumptionService.calculateBatch(r)));assertNull(s.get("settledCompletedQuantity"));assertNull(s.get("averageLoss"));}
 @Test void multipleSettledBatchesUseWeightedAverage(){var first=ProcessConsumptionService.calculateBatch(settled());var second=batch("SETTLED","100","0","40","54");second.put("outputQuantity",2L);second.put("reportId",5L);second.put("reportIssuedWeight","100");second.put("reportReturnedWeight","94");second.put("reportLossWeight","6");second.put("reportAverageLoss","3");second.put("reportCompletedQuantity",2L);second.put("reportVoided",false);var result=ProcessConsumptionService.summarize(List.of(first,ProcessConsumptionService.calculateBatch(second)));assertEquals("16.000000",result.get("settledLossWeight"));assertEquals(12L,result.get("settledCompletedQuantity"));assertEquals("1.333333",result.get("averageLoss"));}
}
